            <DSButton variant={variant} onClick={() => setClickCount((count) => count + 1)}>
              Record click
            </DSButton>
            <DSButton variant={variant} disabled>Disabled</DSButton>
            <DSButton variant={variant} isPending>Working</DSButton>
          </section>
        ))}
      </div>
      <p role="status">Clicks: {clickCount}</p>
      <h2>Inputs</h2>
      <div className={grid}>
        <DSInput label="Text" placeholder="Enter text" />
